// Shared resources are owned by mount, not individual meshes (dispose:null).
export function mount({ React, createRoot, Fiber, THREE, container }) {
  const h=React.createElement,geometry=new THREE.BoxGeometry(.55,.55,.55),material=new THREE.MeshNormalMaterial()
  function Scene({angle,report}){const group=React.useRef(null);const invalidate=Fiber.useThree(s=>s.invalidate);React.useEffect(()=>{if(group.current)group.current.rotation.y=angle;invalidate()},[angle,invalidate]);Fiber.useFrame(()=>{report.current++});return h('group',{ref:group,dispose:null},Array.from({length:36},(_,i)=>h('mesh',{key:i,geometry,material,position:[(i%6-2.5)*.8,(Math.floor(i/6)-2.5)*.8,0],dispose:null})))}
  function App(){const [mode,setMode]=React.useState('demand'),[angle,setAngle]=React.useState(0),[frames,setFrames]=React.useState(0),report=React.useRef(0);React.useEffect(()=>{const id=setInterval(()=>{setFrames(report.current);report.current=0},1000);return()=>clearInterval(id)},[]);return h(React.Fragment,null,h('button',{onClick:()=>setMode(m=>m==='demand'?'always':'demand')},`Mode: ${mode}`),h('button',{onClick:()=>setAngle(a=>a+.3)},'Rotate + invalidate'),h('p',null,`${frames} frames in last second · 36 meshes share 1 geometry/material; instancing can reduce calls.`),h('div',{style:{height:'75%'}},h(Fiber.Canvas,{frameloop:mode,camera:{position:[0,0,8]}},h(Scene,{angle,report}))))}
  const root=createRoot(container);root.render(h(App));return()=>{root.unmount();geometry.dispose();material.dispose()}
}
